// Node 2: Normalize Lead Data
// Extracts variations of form headers, trims whitespace, converts email to lowercase, and preserves row number.
const item = $input.first().json;

// Helper to retrieve case-insensitive matching fields
function getField(keys, defaultVal = '') {
  for (const k of keys) {
    if (item[k] !== undefined && item[k] !== null && String(item[k]).trim() !== '') {
      return String(item[k]).trim();
    }
  }
  return defaultVal;
}

const rawName = getField(['Full Name', 'Name', 'Lead Name', 'name', 'full_name']);
const rawEmail = getField(['Email Address', 'Email', 'email', 'email_address']);
const rawCompany = getField(['Company / Organization', 'Company', 'Organization', 'company', 'organization'], 'Independent Client');
const rawPhone = getField(['Phone Number', 'Phone', 'phone', 'contact_number'], '');
const rawService = getField(['Service Required', 'Service', 'service', 'service_required'], 'AI Workflow Automation');
const rawBudget = getField(['Estimated Budget', 'Budget', 'Budget Range', 'budget', 'budget_range'], '$5,000 - $10,000');
const rawDescription = getField(['Project Scope / Description', 'Project Scope', 'Description', 'description', 'notes'], '');
const existingStatus = getField(['Processing Status', 'Status', 'status'], '');

// Row number preserved for Google Sheets update targeting
const rowNumber = item.__rowNum__ || item.row_number || item['Row Number'] || item.__row_index || null;

return [{
  json: {
    name: rawName,
    email: rawEmail.toLowerCase(),
    company: rawCompany,
    phone: rawPhone || null,
    service: rawService,
    budget: rawBudget,
    description: rawDescription,
    row_number: rowNumber,
    existing_status: existingStatus,
    raw_input: item
  }
}];

// Node 3: Validate Lead Data
// Enforces non-empty name and RFC-5322 compliant email structure.
const item = $input.first().json;

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const hasName = item.name && item.name.length >= 2;
const hasValidEmail = item.email && emailRegex.test(item.email);

let validationError = null;
if (!hasName) {
  validationError = 'Missing or invalid full name (minimum 2 characters required)';
} else if (!hasValidEmail) {
  validationError = `Invalid email address format: '${item.email}'`;
}

if (validationError) {
  return [{
    json: {
      ...item,
      is_valid: false,
      error_reason: validationError
    }
  }];
}

return [{
  json: {
    ...item,
    is_valid: true,
    error_reason: null
  }
}];

